/** v24: authored, optional encounters. No random spawns and no changes to job rules.
 * Shared encounters belong to both lengths; epic encounters sit inside existing chapters.
 * Four action strings follow each campaign's established profession order.
 */
const intent = (name, text, target = 'actor', dc = 12) => ({ name, text, target, damage: 1, dc });
const bypass = (label, text, callback, pressure = 0) => ({ label, text, callback, pressure });
const negotiate = (label, stat, dc, critical, success, failure, fumble) => ({
  label, stat, dc,
  outcomes: {
    critical: { text: critical, method: 'negotiated', pressure: -1 },
    success: { text: success, method: 'negotiated' },
    failure: { text: failure, method: 'bypassed', pressure: 1 },
    fumble: { text: fumble, method: 'fight' }
  }
});
const tool = (id, label, text, callback, consume = false) => ({
  label, requires: { item: id }, useItems: [id], ...(consume ? { consumeItems: [id] } : {}), text, callback
});
